insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 1, 'The third OBEN period is 0.800000 h at 94.600000 dBA, and its OSHA reference duration is 4.228072 h. What share of the OSHA PEL noise dose does that period carry?', '["91.895868 percent, the share the same period carries on the NIOSH noise REL.", "18.921153 percent, the period''s hours over its reference duration.", "23.100555 percent, the share of the 89.800000 dBA period on the action level.", "8.827030 percent, the share of the loudest period."]'::jsonb, 1, 'A contribution is the period''s hours divided by its reference duration, in percent: 0.800000 over 4.228072 is 18.921153 percent. The tempting 91.895868 percent is the same period on the NIOSH noise REL, where the reference duration at 94.600000 dBA is only 0.870551 h, so it answers a different criterion than the one asked.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 2, 'Which statement defines the reference duration the engine returns from `noiseReferenceDurationH`?', '["The time the dosimeter actually recorded at that sound level during the shift being assessed.", "The 8 hours of a standard shift, against which every period is divided whatever its level.", "The time left at a level once the periods already on the record have been subtracted.", "The time at a sound level that gives exactly 100 percent noise dose on the named criterion."]'::jsonb, 3, 'Digest section 4 defines it as the time at a level that gives exactly 100 percent noise dose, so it belongs to the criterion and the level and not to the record. The recorded hours are the numerator of a contribution and the reference duration is its denominator; mixing them up inverts the arithmetic. The time left at a level is a later derived quantity.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 3, 'On the OSHA criterion, T = 8 / 2^((L - 90)/5) hours. What reference duration does the engine give at 100.000000 dBA?', '["2.000000 h, two steps of 5 dB above the 90 dBA criterion level.", "0.793701 h, which is what a 3 dB step up from the 90 dBA level would give.", "0.250000 h, the NIOSH reference duration at the same sound level.", "4.000000 h, the OSHA reference duration at 95.000000 dBA."]'::jsonb, 0, '100 dBA is 10 dB above 90, which is two 5 dB steps, so 8 hours halves twice to 2.000000 h. The tempting 0.793701 h comes from using a 3 dB step with the OSHA criterion level; that is the same figure NIOSH gives at 95.000000 dBA, and it mixes the two criteria. 0.250000 h is NIOSH''s own answer at 100.000000 dBA.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 4, 'OSHA Table G-16a prints 0.063 at 125 dBA, while the engine returns 0.062500 h. What does the difference mean?', '["The engine is off by 0.000500 h and needs the printed row pasted into its tables.", "OSHA used a 3 dB decibel exchange rate for the loud rows at the top of the table.", "The printed 0.063 is a round-half-up of the fourth decimal of the formula''s 0.062500.", "Above 115 dBA the table stops following the formula and prints measured values."]'::jsonb, 2, 'Digest section 4 says it: the formula gives exactly 0.062500 h and the table prints 0.063, a round-half-up of the fourth decimal. The difference is the table''s rounding, so treating the printed figure as the true one takes the rounding for the physics. Every other G-16a row sits inside its printed tolerance in the same way.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 5, 'The OSHA criteria carry a decibel exchange rate of 5.000000000000 dB. How does the engine measure it?', '["It asks for the level giving a 2 hour reference duration, 100.000000 dBA, and subtracts the 90 dBA criterion level.", "It reads the step between two adjacent rows of Table G-16a and averages the 51 steps across the whole table.", "It asks for the level giving a 4 hour reference duration, 95.000000 dBA, and subtracts the 90 dBA criterion level.", "It takes the printed TWA coefficient 16.61 and divides it by the 8 hours of the standard shift."]'::jsonb, 2, 'Digest section 3 gives the method: the level for a 4 hour reference duration less the criterion level. On OSHA that is 95.000000 less 90.000000, so 5 dB halves the time. The 2 hour level is two halvings away and would read 10 dB, twice the rate, and G-16a rows are one decibel apart, so their steps measure nothing about the rate.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 6, 'Using only each criterion''s decibel exchange rate, at what level does the NIOSH reference duration reach 1.000000 h?', '["94.000000 dBA, three 3 dB steps above 85.", "105.000000 dBA, three 5 dB steps above 90.", "91.000000 dBA, where NIOSH gives 2.000000 h.", "88.000000 dBA, one step above 85."]'::jsonb, 0, 'From 8 hours at 85 dBA, three halvings reach 1 hour, and each costs 3 dB on NIOSH, so 85 plus 9 is 94.000000 dBA, which is 60.000000 minutes in Table 1-1. The tempting 105.000000 dBA is the OSHA ladder, 5 dB a step from 90. 91.000000 dBA is only two halvings, which gives 2.000000 h.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 7, 'On the OBEN record, how many of the six periods does the OSHA PEL setup integrate?', '["5 of the 6, because every period at or above 80 dBA counts toward the noise dose.", "2 of the 6, because only 94.600000 and 99.100000 dBA reach its 90 dBA threshold.", "3 of the 6, because 89.800000 dBA rounds up to the 90 dBA threshold on the day.", "6 of the 6, because the threshold only changes the TWA and never the noise dose."]'::jsonb, 1, 'The PEL threshold is 90.000000000000 dBA, so only the third and fifth periods count. The tempting 5 of 6 is what the OSHA action level and the NIOSH noise REL integrate, because their threshold is 80. A level of 89.800000 dBA is under 90 and the engine does not round it up.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 8, 'The second OBEN period is 1.900000 h at 89.800000 dBA. What does it add to the OSHA PEL noise dose?', '["23.100555 percent, the same as on the action level, because both setups share a criterion level.", "71.996537 percent, since its reference duration is 2.639016 h at that sound level.", "A fifth of a decibel''s worth, since the engine prorates a period near the threshold.", "Nothing, since it is under the PEL threshold of 90 dBA."]'::jsonb, 3, 'A period below the threshold contributes nothing however long it lasts. The tempting 23.100555 percent is the action level''s figure: that setup shares the PEL''s criterion level and decibel exchange rate, but its threshold is 80, so it lets this period in and the PEL does not. 71.996537 percent is the NIOSH noise REL contribution.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 9, 'ORONI places 2.000000 h exactly on 90.000000 dBA. How much of the PEL allowance does the engine count for those hours?', '["25.000000 percent, since judgement J2 makes the threshold inclusive.", "Nothing, since a period sitting on the threshold is below it and left out.", "79.370053 percent, the NIOSH noise REL share of that very same period.", "9.375000 percent, the action level share of the ORONI 80 dBA period."]'::jsonb, 0, 'Judgement J2 is that the threshold is inclusive, so a period exactly at 90 dBA is integrated on the PEL: 2 hours over an 8 hour reference duration is 25.000000 percent. Reading the line as exclusive would drop the period, which is the choice the engine did not make. 79.370053 percent is the NIOSH noise REL contribution of the same period.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 10, 'The ORONI record also has 3.000000 h at 79.900000 dBA. Under which of the three criteria in this tier is that period integrated?', '["Under the OSHA action level and the NIOSH noise REL, whose thresholds are both 80 dBA.", "Under the NIOSH noise REL alone, whose criterion level is only 85 dBA.", "Under none of them, because 79.900000 dBA is below every threshold in this tier.", "Under all three, since every hour the dosimeter records counts."]'::jsonb, 2, 'The thresholds are 90 dBA on the PEL and 80 dBA on the action level and the NIOSH noise REL, so a period a tenth of a decibel under 80 counts nowhere. The tempting answer treats 79.900000 as if it reached 80; J2 makes a period exactly on 80 count, and this one is below it.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 11, 'A script asks `noiseReferenceDurationH` for the preset ''ACGIH''. What does the engine return?', '["A reference duration on the OSHA PEL, the preset the engine falls back to when a name is not recognised.", "A refusal on `criterion`, saying the name is unknown and listing OSHA_PEL, OSHA_ACTION_LEVEL and NIOSH_REL.", "A refusal on `levelDbA`, since the level cannot be checked until a known criterion has been named.", "A reference duration computed from a limit table the engine keeps for licensed criteria of this kind."]'::jsonb, 1, 'The engine''s own words are "criterion ''ACGIH'' is unknown: use one of OSHA_PEL, OSHA_ACTION_LEVEL, NIOSH_REL or pass the parameters", on the field `criterion`. It never falls back to a default, which would print a number the caller did not ask for. The engine embeds no licensed limit table.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 12, 'A download''s first period has a negative duration. Which field does the engine name in its refusal?', '["`periods`, since the record is refused as one whole list of periods.", "`dosePct`, since a negative period would yield a negative total.", "`periods[0].levelDbA`, pointing at the first period''s level.", "`periods[0].durationH`, pointing at the first period''s hours."]'::jsonb, 3, 'The golden case dose-negative-duration refuses on `periods[0].durationH` with the message "periods[0].durationH cannot be negative". The refusal names the period by position so a hygienist can go straight to the row. `periods` is the field for an empty record or one over 24 hours, and `dosePct` belongs to the TWA door.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 13, 'An input a function cannot use arrives. What does the engine return in place of a number?', '["An object carrying `error` and `field`, the name of the input it refused.", "A verdict that the record exceeds its limit noise dose, so no number is needed.", "A logged message resent to the dosimeter, which reads that period again.", "A noise dose of zero, since the criterion cannot integrate that input."]'::jsonb, 0, 'Digest section 1: every function returns a finite result or an object carrying `error` and `field`, the name of the input it refused, so a refusal is a statement about the data handed over. It is no verdict on the worker or the workplace, and the engine does nothing to the instrument. A noise dose of zero is what a real record with nothing above the threshold returns.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 14, 'One OBEN record reads 27.748183 percent on the OSHA PEL and 265.610944 percent on the NIOSH noise REL. What is the right reading of the two figures?', '["The NIOSH figure is correct and the PEL figure misses periods the dosimeter logged.", "Both are correct, since each is a fraction of its own criterion''s allowance.", "The PEL figure is correct and NIOSH double counts the periods above 90 dBA.", "One has a units error, since a single record can only give one noise dose."]'::jsonb, 1, 'A noise dose is a fraction of an allowance, and the allowance belongs to a criterion, so the same record supports both numbers. The PEL leaves out periods below its 90 dBA threshold by design, which is the criterion at work. Nothing is double counted on NIOSH: its allowance is smaller, so each period carries a larger share.'),
  ('hygiene', 'beginner', 'module', 'm01-what-a-dosimeter-day-is', 15, 'A noise dose of exactly 100 percent on a named criterion means what?', '["The day''s loudest period reached the criterion level of that criterion.", "Every period on the record was integrated, since none fell below threshold.", "The day has used exactly one day''s allowance on that criterion.", "The worker spent all 8 hours at the criterion level, and at no other level."]'::jsonb, 2, 'Below 100 percent some allowance remains and above 100 the day used more than one allowance, so 100 means exactly used up. Spending the whole reference duration at one level is one way to reach it, and many mixes of periods reach it too, so the 8 hours at the criterion level is a single case. The percentage says nothing about which period was loudest.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 1, 'The OBEN day gives an OSHA PEL noise dose of 27.748183 percent. What TWA does the engine report beside it?', '["87.635749 dBA, the TWA the OSHA action level reports for that day.", "89.242460 dBA, the NIOSH noise REL TWA for the very same record.", "80.752126 dBA, from 16.61 log10(D/100) + 90 on that noise dose.", "90.000000 dBA, the PEL criterion level, as the TWA of any day."]'::jsonb, 2, 'The TWA is the constant level that would give the same noise dose over 8 hours: 16.61 times log10 of 27.748183 over 100, plus 90, is 80.752126 dBA. It sits below 90 because the noise dose sits below 100 percent. The tempting 87.635749 dBA belongs to the action level, which integrates more periods and so restates a larger noise dose.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 2, 'At a noise dose of exactly 100 percent, what TWA do OSHA Table A-1 and NIOSH Table 1-2 give?', '["90.000000 dBA on OSHA and 85.000000 dBA on NIOSH, each its own criterion level.", "85.000000 dBA on both, since 100 percent is the same allowance on either scale.", "90.000000 dBA on both, since the TWA is always stated on the OSHA scale of 90.", "80.000000 dBA on both, the level where the two tables'' thresholds begin."]'::jsonb, 0, 'At 100 percent the logarithm term is zero and the TWA equals the criterion level Lc, which is 90 for OSHA and 85 for NIOSH. The tempting answer treats the two scales as one; they have different criterion levels, so the same percentage restates as different levels. 80 dBA is a threshold and plays no part in the TWA formula.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 3, 'Which coefficient does the engine''s OSHA PEL preset use in TWA = K log10(D/100) + 90, and why?', '["16.609640474437, because the engine always prefers the exact coefficient to a printed one.", "10.0, because the engine uses one printed coefficient for all three presets alike.", "16.61 on the PEL and the exact coefficient on the action level of the same record.", "16.61, because judgement J1 has each preset use the coefficient its source prints."]'::jsonb, 3, 'Judgement J1: each preset uses the coefficient its source prints, 16.61 for OSHA and 10.0 for NIOSH, and only a criterion typed by hand defaults to the exact decibel exchange rate over log10 2. The exact 16.609640474437 is what the custom default would use. The PEL and action level presets both measure 16.610000000000.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 4, 'OSHA Table A-1 does not separate 16.61 from the exact coefficient. What, then, fixes 16.61 for OSHA?', '["Table A-1, whose rows reject the exact coefficient wherever the two disagree.", "The text of the mandatory Appendix A, which writes TWA = 16.61 log10(D/100) + 90.", "NIOSH Table 1-2, whose 49 rejecting rows settle the coefficient for both agencies.", "The engine''s bisection on its own output, which finds 16.61 as a best fit."]'::jsonb, 1, 'The two OSHA coefficients differ by 0.000359525563 dB and the table prints one decimal, so 0 of its 150 rows reject the exact one. The regulation''s text is what writes 16.61, and the course records that as a decision grounded in the text. Table 1-2 speaks only for NIOSH''s 10.0, so it cannot settle the OSHA coefficient.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 5, 'Of the 83 rows of NIOSH Table 1-2, how many fall outside their printed tolerance when the exact coefficient replaces 10.0?', '["0, since both coefficients round to the same printed decimal.", "150, every row, since the exact coefficient is refuted.", "49, which is why this table supports the printed 10.0.", "83, since the table was typed from the exact values."]'::jsonb, 2, 'Digest section 5: with the exact coefficient 49 of the 83 printed rows fall outside their printed tolerance, so the table was computed with the coefficient NIOSH prints. The tempting 0 is the OSHA Table A-1 result, 0 of 150, because the OSHA gap is too small to move a printed decimal. Some NIOSH rows, such as 20.000000 percent, cannot tell the two apart.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 6, 'Eight hours at a constant 100 dBA on the NIOSH preset: what TWA does the engine report?', '["100.051500 dBA, a little above the level, the cost of the printed 10.0.", "100.000000 dBA, since a constant level always returns itself as its TWA.", "97.000000 dBA, since the NIOSH scale sits 3 dB below the OSHA scale.", "85.000000 dBA, since a TWA on NIOSH is stated at its criterion level."]'::jsonb, 0, 'Digest section 5 measures 100.051500 dBA on the NIOSH preset, where the level itself is 100. The tempting 100.000000 dBA is what a custom criterion with the exact coefficient returns for the same record. The printed 10.0 sits 0.034215715338 dB above the exact coefficient, and that excess is what lifts the TWA above the constant level.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 7, 'A criterion typed by hand, with no coefficient given, has a 4 dB decibel exchange rate. Which TWA coefficient does the engine default to?', '["16.61, the OSHA printed value used for every criterion.", "10.0, the NIOSH printed value used for every criterion.", "No coefficient: it refuses on `twaCoefficientDb` instead.", "The exact one, the decibel exchange rate over log10 2."]'::jsonb, 3, 'Judgement J1 says a custom criterion defaults to the exact decibel exchange rate over log10 2; only the presets use a printed coefficient. The printed 16.61 and 10.0 belong to the OSHA and NIOSH presets. `twaCoefficientDb` is refused only when a coefficient is supplied and is not a finite number above zero, which is a different case.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 8, 'Eight hours at 85 dBA are run on the OSHA PEL setup. What does `noiseDose` return?', '["A noise dose of 0.000000 percent and a TWA of 0 dBA for the day.", "A noise dose of 0.000000 percent and a TWA reported as absent, null.", "A refusal on `dosePct`, since a zero noise dose has no TWA to give.", "A noise dose of 50.000750 percent and a TWA of 85.000000 dBA."]'::jsonb, 1, 'Nothing in the record reaches the PEL threshold of 90 dBA, so nothing is integrated, and the engine returns a noise dose of zero with a TWA of null. A record with nothing above the threshold is a legitimate day, so `noiseDose` does not refuse. A TWA of 0 dBA would claim a sound level nobody measured. 50.000750 percent is the OSHA noise dose for a TWA of 85.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 9, 'A script asks `noiseTwaFromDoseDbA` for the TWA of a noise dose of 0. What comes back?', '["A TWA of null with a noise dose of zero, the same answer `noiseDose` gives for a quiet day.", "A TWA equal to the criterion''s threshold, the lowest level the criterion can integrate.", "A refusal on `dosePct`: \"dosePct must be a finite percentage above zero: a zero dose has no TWA\".", "A TWA of negative infinity, since the logarithm of zero tends to it as the noise dose falls."]'::jsonb, 2, 'This door is asked a direct question with an impossible input, so it refuses on `dosePct` in the engine''s own words quoted in the key. The null TWA belongs to `noiseDose`, which is reading a real record and so reports what it found. The logarithm of zero is not a number, and the engine will not invent one.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 10, 'OSHA Table A-1 turns a noise dose of 10.000000 percent into 73.390000 dBA, which is below the PEL threshold. What does that TWA mean?', '["It is an error, since a TWA can never sit below its threshold.", "It is the sound level of the quietest period on that record.", "It shows that record''s noise dose should have been refused.", "The level that, held for 8 hours, gives that same noise dose."]'::jsonb, 3, 'A TWA is a restatement of the percentage, the constant level over 8 hours that gives the same noise dose, and it can sit below the threshold whenever the percentage is small. The OBEN PEL TWA of 80.752126 dBA sits below 90 for the same reason. Nothing about it describes one period, and the engine refuses only a noise dose of zero or below.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 11, 'NIOSH Table 1-2 prints 121.500000 dBA for a noise dose of 450000.000000 percent. The engine gives 121.532125 with 10.0 and 121.407128 with the exact coefficient. What does the row show?', '["It rejects the exact coefficient, whose 121.407128 rounds to a decimal the table does not print.", "It cannot separate them, since both engine columns round to the printed 121.500000 dBA.", "It rejects 10.0, since 121.532125 is further from the printed figure than the exact one.", "It shows the table was typed with a 5 dB decibel exchange rate for the top of its range."]'::jsonb, 0, 'At one decimal the printed 10.0 gives the table''s own figure, and the exact coefficient''s 121.407128 rounds one decimal lower, to a figure the table does not print. That makes the row one of the 49 that reject the exact coefficient. A row such as 20.000000 percent is the kind that cannot separate them, because both columns round to the printed 78.000000 dBA.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 12, 'On OSHA Table A-1 at a noise dose of 45.000000 percent, the engine gives 84.239860 with 16.61 and 84.239985 with the exact coefficient; the table prints 84.200000. Which coefficient does the row support?', '["16.61, since 84.239860 is the nearer of the two to 84.200000.", "Neither over the other: both round to the printed 84.200000.", "The exact one, since it is the larger of the two and so rounds up.", "Neither, since the row sits outside its printed tolerance under both."]'::jsonb, 1, 'Rounded to the table''s one decimal, both engine columns land on the printed 84.200000, so the row is consistent with either coefficient. Being a little nearer the printed value decides nothing when the table cannot resolve the difference, which is exactly why the text of Appendix A fixes 16.61 and Table A-1 cannot. The row sits inside its tolerance under both.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 13, 'On OSHA Table A-1, doubling the noise dose to 200.000000 percent gives 95.000108 dBA. Why is it a little above 95?', '["Because Table A-1 adds a rounding margin at each whole doubling.", "Because 200 percent crosses the PEL limit and triggers a correction.", "Because the printed 16.61 sits slightly above the exact coefficient.", "Because the threshold of 90 dBA shifts the TWA by a small offset."]'::jsonb, 2, 'Doubling the noise dose adds the coefficient times log10 2 to the TWA. With the exact coefficient that is exactly 5 dB, and Table A-1''s exact column gives 95.000000; with 16.61 it is slightly more, so the engine gives 95.000108 dBA. The table prints 95.000000 either way. No correction is applied at the limit and the threshold plays no part in the TWA formula.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 14, 'How far above its exact value does each printed TWA coefficient sit?', '["OSHA by 0.000359525563 dB and NIOSH by 0.034215715338 dB.", "OSHA by 0.034215715338 dB and NIOSH by 0.000359525563 dB.", "Both by 0.000359525563 dB, since both round to two decimals.", "Both by exactly 0.034215715338 dB, the NIOSH gap on both."]'::jsonb, 0, 'The exact coefficients are 16.609640474437 for 5 dB and 9.965784284662 for 3 dB, so 16.61 sits 0.000359525563 dB above its exact value and 10.0 sits 0.034215715338 dB above its own. The swapped pairing is the tempting error; the NIOSH gap is the larger one, which is why NIOSH Table 1-2 can tell its coefficients apart and OSHA Table A-1 cannot.'),
  ('hygiene', 'beginner', 'module', 'm02-from-noise-dose-to-twa', 15, 'Four times the OSHA allowance, 400.000000 percent, restates as 100.000216 dBA with the printed coefficient and 100.000000 dBA with the exact one. What figure does Table A-1 print for it?', '["100.000216 dBA, the figure the printed 16.61 gives there.", "100.000000 dBA, which both engine columns round to.", "95.000000 dBA, one decibel exchange rate below that level.", "90.000000 dBA, the criterion level of the PEL."]'::jsonb, 1, 'Four times the allowance is two doublings, so the TWA is two 5 dB steps above 90, near 100 dBA. The printed row is 100.000000 dBA and both engine columns round to it, so this row, like every row of Table A-1, cannot separate the two OSHA coefficients. 95.000000 is the row for 200.000000 percent, one doubling.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 1, 'Of the four numbers that define the OSHA PEL setup, which two are the same figure?', '["The criterion level and the limit noise dose, both 90.", "The threshold and the decibel exchange rate, both 5.", "The limit noise dose and the threshold, both at 100 percent.", "The criterion level and the threshold, both 90 dBA."]'::jsonb, 3, 'The PEL setup is a criterion level of 90.000000000000 dBA, a decibel exchange rate of 5.000000000000 dB, a threshold of 90.000000000000 dBA and a limit noise dose of 100.000000000000 percent. The criterion level and the threshold coincide, which is why the PEL is so selective: a period has to be as loud as the eight-hour level before it counts. The limit noise dose is a percentage and cannot equal a level.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 2, 'Moving from the OSHA PEL setup to the OSHA action level setup, which parts of the criterion change?', '["The criterion level drops to 85 dBA and the decibel exchange rate to 3 dB.", "The threshold drops to 80 dBA and the limit noise dose halves to 50 percent.", "Only the limit noise dose halves to 50 percent; the threshold stays at 90 dBA.", "The threshold drops to 80 dBA; the limit noise dose stays at 100 percent."]'::jsonb, 1, 'Two numbers change: the threshold becomes 80.000000000000 dBA and the limit noise dose 50.000000000000 percent, while the criterion level stays at 90 and the decibel exchange rate at 5 dB. The tempting 85 dBA and 3 dB belong to the NIOSH noise REL. Changing only the limit would leave the OBEN day at 2 integrated periods; the lower threshold is what lets 5 in.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 3, 'On the OSHA action level setup, what noise dose and TWA does the OBEN day give?', '["72.054478 percent and 87.635749 dBA, against a limit of 50 percent and 85 dBA.", "27.748183 percent and 80.752126 dBA, since the action level and the PEL share a criterion level.", "265.610944 percent and 89.242460 dBA, since both use the 80 dBA threshold.", "50.000000 percent and 85.000000 dBA, the limit the action level sets."]'::jsonb, 0, 'The action level integrates 5 of the 6 periods, and their contributions add to 72.054478 percent, which restates as 87.635749 dBA with 16.61. The PEL figures of 27.748183 and 80.752126 come from the same criterion level but only 2 integrated periods. The NIOSH noise REL shares the 80 dBA threshold and differs in criterion level and decibel exchange rate.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 4, 'Section 1910.95(c)(1) sets the action level at a TWA of 85 dBA "or, equivalently, a dose of fifty percent". What noise dose does `noiseDoseFromTwaPct` give for a TWA of 85 on the OSHA scale?', '["50.000000 percent exactly, since the regulation says the two are equivalent.", "100.000000 percent, since 85 dBA is the NIOSH noise REL criterion level.", "50.000750 percent, a hair over 50 because of the printed 16.61.", "25.000750 percent, since the action level is half of the PEL''s half."]'::jsonb, 2, 'The engine measures 50.000750 percent. With the exact coefficient a TWA of 85 would be exactly half the allowance; the printed 16.61 moves it by a tiny amount, and at the precision the regulation writes the two are the same point. 100.000000 percent is what a TWA of 85 gives on the NIOSH scale. 25.000750 percent is the OSHA noise dose for a TWA of 80.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 5, 'What are the criterion level, decibel exchange rate and threshold of the NIOSH noise REL?', '["90 dBA, 5 dB and 80 dBA.", "85 dBA, 5 dB and 85 dBA.", "85 dBA, 3 dB and 85 dBA.", "85 dBA, 3 dB and 80 dBA."]'::jsonb, 3, 'Digest sections 3 and 7 give the NIOSH noise REL a criterion level of 85.000000000000 dBA, a decibel exchange rate of 3.000000000000 dB and a threshold of 80.000000000000 dBA. The first distractor is the OSHA action level. Setting the threshold at the criterion level is the PEL''s pattern, and NIOSH does not follow it: its threshold is five decibels lower.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 6, 'The first OBEN period, 2.600000 h at 84.300000 dBA, carries 27.646683 percent on the NIOSH noise REL and 14.747186 percent on the OSHA action level. Why the larger NIOSH share?', '["NIOSH counts the period''s hours twice, once for level and once for time.", "Its NIOSH reference duration is 9.404383 h, against 17.630482 h on OSHA.", "NIOSH rounds the level up to 85 dBA before it finds the reference duration.", "The action level halves every share, since its limit is only 50 percent."]'::jsonb, 1, 'Both criteria integrate the period, since 84.300000 dBA is above both 80 dBA thresholds, so only the denominator differs. NIOSH''s lower criterion level and 3 dB decibel exchange rate make its allowance at that level last 9.404383 h, against 17.630482 h on OSHA. The action level''s limit of 50 percent is only the line the total is read against and changes no share.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 7, 'The OBEN NIOSH noise REL noise dose is 265.610944 percent. What TWA does TWA = 10.0 log10(D/100) + 85 give?', '["89.242460 dBA.", "87.635749 dBA, the action level.", "80.752126 dBA, the PEL.", "85 dBA."]'::jsonb, 0, 'Ten times log10 of 265.610944 over 100, plus 85, is 89.242460 dBA, above 85 because the noise dose is above 100 percent. 87.635749 dBA is the OSHA action level TWA and 80.752126 dBA the PEL TWA of the same day. 85 dBA is the TWA only at exactly 100 percent.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 8, 'The OBEN day is under one criterion and over two. Which of its three noise doses is the real one?', '["The NIOSH figure, since it counts every period at or above 80 dBA on the record.", "The PEL figure, since it is the only one written in a regulation with a limit.", "The action level figure, since it sits between the other two noise doses.", "None of the three alone; each is the noise dose against its own criterion."]'::jsonb, 3, 'Digest section 7 says it directly: none of the three is the real noise dose, and a report that quotes a noise dose without naming the criterion has not said anything. The action level also counts every period from 80 dBA and is also written in regulation, so neither of those reasons singles out one figure. Sitting between the others is no reason at all.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 9, 'The OBEN action level noise dose is 72.054478 percent and the PEL noise dose 27.748183 percent. Which difference between the two criteria makes that whole gap?', '["The limit noise dose, which halves to 50 percent and so doubles every share on the whole record.", "The criterion level, which moves the reference duration of every integrated period.", "The threshold, which lets in three periods worth 14.747186, 23.100555 and 6.458554 percent.", "The decibel exchange rate, which is steeper on the action level for the louder periods of the day."]'::jsonb, 2, 'The two OSHA setups share a criterion level and a decibel exchange rate, so every period they both integrate carries the same share. The whole gap is the three periods the lower threshold lets in. The limit noise dose changes only the line the total is compared with and moves no contribution, which is the tempting mistake.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 10, 'The fifth OBEN period, 0.200000 h at 99.100000 dBA, carries 8.827030 percent on OSHA and 64.980192 percent on the NIOSH noise REL. What produces the difference?', '["The threshold, since NIOSH lets the period in at 80 dBA while OSHA admits it only partly.", "The lower criterion level and the 3 dB decibel exchange rate, which shorten its NIOSH reference duration.", "The limit noise dose, since NIOSH divides every contribution by a limit twice as large.", "The NIOSH ceiling of 115 dBA, which adds a penalty to any period louder than 95 dBA."]'::jsonb, 1, 'The level and hours are identical, so only the reference duration moves: 2.265768 h on OSHA against 0.307786 h on NIOSH. Both a lower criterion level and a 3 dB step shrink the NIOSH allowance, and the steep step weighs loud short periods most. The period is above both thresholds, so the threshold plays no part here, and 99.100000 dBA is far below the 115 dBA ceiling.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 11, 'On the OSHA PEL setup the engine reports `exceedsLimit` false for the OBEN day. What does that flag say?', '["The PEL noise dose is under the PEL limit noise dose of 100 percent, and nothing more.", "The day is under every criterion, since the PEL is the only regulatory limit here.", "No period on the record reached a sound level at or above the PEL threshold of 90 dBA.", "The day needs no action level programme, since the PEL is the stricter of the two."]'::jsonb, 0, 'The flag compares one noise dose with one limit. The same record is over the action level and over the NIOSH noise REL, so false on the PEL says nothing about either. Two periods did reach the PEL threshold and made the whole 27.748183 percent. The course never grades a verdict word because a verdict means nothing without its criterion.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 12, 'A 117 dBA period on the OSHA PEL setup gives a noise dose of 52.780316 percent, under the PEL limit. What should a report take from the engine''s output?', '["That the period is acceptable, since its noise dose is under 100 percent.", "That the engine refused it, since no level over 115 dBA can be integrated.", "That the figure is extrapolated, since 117 dBA is past the top of Table G-16a.", "The warning, since the level is above anything Table G-16 permits."]'::jsonb, 3, 'The engine warns "a level of 117 dBA is above 115 dBA, the highest level Table G-16 permits" and still integrates it, which is judgement J3. A noise dose under its limit does not clear a level above a ceiling, so the warning comes before the percentage. The extrapolation warning applies only above 130 dBA, the top of Table G-16a.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 13, 'A 132 dBA period on the OSHA PEL setup gives 84.448506 percent. How many warnings does the engine attach, and what does it do with the period?', '["1 warning, and it drops the period from the noise dose.", "No warning, since the noise dose is under the PEL limit.", "2 warnings, and it still integrates the period under J3.", "A refusal on the level, since it is past every table."]'::jsonb, 2, 'Judgement J3: above 130 dBA and above 115 dBA the result warns and still integrates. At 132 dBA both apply, the Table G-16a extrapolation and the Table G-16 maximum, so there are 2 warnings, and the TWA is 88.780693 dBA. The engine refuses records that cannot be computed; a very loud period can be, so it is reported with its warnings beside it.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 14, 'A 117 dBA period is run on the NIOSH noise REL. Which warning, in the engine''s own words, does it carry?', '["\"a level of 117 dBA is above 130 dBA, the top of Table G-16a: the formula is extrapolated there\"", "\"a level of 117 dBA exceeds the 115 dBA ceiling of this criterion, whatever the dose\"", "No warning, because the NIOSH noise REL criterion has no ceiling of its own", "A refusal on `levelDbA`, since NIOSH does not integrate levels above 115"]'::jsonb, 1, 'The ceiling on the NIOSH noise REL preset is 115 dBA, and the engine''s own message for 117 dBA is the one in the key; the noise dose is 2156.290550 percent with 1 warning. The extrapolation message belongs above 130 dBA only, and 117 is below it. The engine never refuses a loud period for its level; it warns and integrates.'),
  ('hygiene', 'beginner', 'module', 'm03-three-criteria-one-record', 15, 'A European colleague asks whether the OBEN action level result is an "action value". What is the right answer?', '["No: the action level is the OSHA hearing conservation trigger, while EU action values are LEX,8h levels, a different metric.", "Yes: the action level and the EU action values are two names for the same 85 dBA line, so they compare directly.", "Yes, once the noise dose of 72.054478 percent has been restated as a TWA of 87.635749 dBA.", "No, because EU action values are measured in noise dose percent and the action level is in dBA."]'::jsonb, 0, 'Digest section 24 puts the two on the same footing as a misreading: "Action level" is the OSHA hearing conservation trigger, and the EU uses action values, which are LEX,8h levels and a different metric. Restating the noise dose as a TWA does not turn it into a LEX,8h, and the EU values are levels in dBA.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 1, 'The engine''s `noiseDose` door returns one contribution per period. What is a contribution?', '["The period''s hours divided by its reference duration at that level, in percent.", "The period''s hours divided by the 8 hours of the day, weighted by its level.", "The period''s sound level less the criterion level, multiplied by the hours it lasted.", "The period''s share of the day''s TWA, in dBA, before the logarithm."]'::jsonb, 0, 'Digest section 7 gives each period''s reference duration as the denominator of its contribution, and the noise dose is the sum of those shares. Dividing by the 8 hours of the day ignores the level entirely except through a weight the engine does not use. Contributions are percentages of an allowance, and the TWA is computed only from their total.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 2, 'On the action level, period 1 lasts 2.600000 h and carries 14.747186 percent, while period 2 lasts only 1.900000 h and carries 23.100555 percent. Why does the shorter period carry more?', '["Period 2 is nearer the PEL threshold of 90 dBA, so the action level gives it extra weight near that line.", "Period 1 is partly below the action level threshold, so only part of its hours are integrated.", "Period 2 is louder by more than one 5 dB step, so its reference duration is 8.224911 h against 17.630482 h.", "Period 2 falls later in the shift, and the engine weights later periods more heavily on the day."]'::jsonb, 2, 'A contribution is hours over reference duration. At 89.800000 dBA the OSHA reference duration is 8.224911 h and at 84.300000 dBA it is 17.630482 h, so the louder period uses its allowance more than twice as fast. Hours matter and level matters more. Both periods are above the 80 dBA threshold in full, and the engine has no position weighting.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 3, 'The third OBEN period carries 18.921153 percent on both the OSHA PEL and the OSHA action level. Why the same figure?', '["Both setups share the same limit noise dose, so the period is divided by the same figure under each criterion.", "Both setups share a criterion level and a decibel exchange rate, so the reference duration is the same.", "The action level caps the period at the PEL value because it is above 90 dBA.", "The engine copies the PEL contribution into the action level for loud periods."]'::jsonb, 1, 'A contribution depends on the level, the hours and the reference duration, and the reference duration depends on the criterion level and the decibel exchange rate, which both OSHA setups share. The limit noise dose differs, 100 against 50 percent, and it moves no contribution. The threshold only matters for the quieter periods, which this one is not.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 4, 'Period 4 of the OBEN record is 1.750000 h at 81.200000 dBA, with an OSHA reference duration of 27.095850 h. What does the OSHA PEL column show for it, and why?', '["6.458554 percent, its 1.750000 h over its 27.095850 h reference duration.", "9.091664 percent, its hours over the NIOSH reference duration at 81.200000 dBA.", "Not integrated, because its reference duration exceeds 24 h, a whole day.", "Not integrated, because 81.200000 dBA is below the PEL threshold."]'::jsonb, 3, 'Dividing 1.750000 by 27.095850 gives 6.458554 percent, and the action level reports exactly that, but the PEL integrates nothing under 90 dBA, so the division is never made. 9.091664 percent is the NIOSH noise REL share. A reference duration longer than a day is normal and is no reason to leave a period out.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 5, 'What share of the OBEN day''s PEL noise dose does the loudest period, 99.100000 dBA for 0.200000 h, carry?', '["31.811200 percent, the smaller of the two terms.", "64.980192 percent, its share on the NIOSH noise REL.", "8.827030 percent, which is the whole share.", "100 percent, since it is the loudest period."]'::jsonb, 0, 'The loudest period contributes 8.827030 percent of the allowance, and that is 31.811200 percent of the day''s 27.748183 percent. The tempting 8.827030 confuses a contribution to the allowance with a share of the day''s total. The larger term belongs to the 94.600000 dBA period, quieter and four times as long.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 6, 'Why does the 94.600000 dBA period carry more of the PEL noise dose than the 99.100000 dBA period?', '["Its sound level is closer to the criterion level, and the PEL weights levels close to 90 dBA most heavily.", "The engine scales each period by the square of its hours before dividing by the reference duration.", "It lasts four times as long while its reference duration is under twice as long, 4.228072 against 2.265768 h.", "The louder period is past a table top, so the engine trims its contribution to the printed maximum."]'::jsonb, 2, 'Contribution is hours over reference duration: 0.800000 over 4.228072 h against 0.200000 over 2.265768 h. The louder period costs more per minute and has far fewer minutes. There is no weighting by nearness to 90 dBA and no squaring of hours, and 99.100000 dBA is well under any table top, so nothing is trimmed.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 7, 'On the NIOSH noise REL, how does the OBEN day''s loudest period rank among the three periods that each carry more than half a day''s allowance?', '["It is the largest of the three, at 91.895868 percent.", "It is the smallest of the three, at 64.980192 percent.", "It sits in the middle of the three, at 71.996537 percent.", "It is not among them, being worth only 8.827030 percent."]'::jsonb, 1, 'On NIOSH the three big terms are 91.895868 percent from the 94.600000 dBA period, 71.996537 percent from the 89.800000 dBA period and 64.980192 percent from the 99.100000 dBA period. The loudest reading is the smallest of them. 8.827030 percent is that period''s OSHA share, which answers a different criterion.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 8, 'After the OBEN day, what share of the OSHA PEL allowance remains?', '["72.054478 percent.", "27.748183 percent.", "50.000000 percent.", "72.251817 percent."]'::jsonb, 3, 'The PEL noise dose after the day is 27.748183 percent, so 100 less that leaves 72.251817 percent. The tempting 72.054478 percent is the day''s action level noise dose, a near-identical figure from a different criterion. 27.748183 percent is the share used, and 50.000000 percent is the action level limit noise dose, which belongs to another criterion.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 9, 'With 72.251817 percent of the PEL allowance left and an OSHA reference duration of 4.000000 h at 95 dBA, how long could the worker spend at 95 dBA for the rest of the day?', '["173.404361 minutes, which is 2.890073 h.", "240.000000 minutes, the whole 4.000000 h.", "2.890073 minutes, the fraction times 4.", "480.000000 minutes, the 8 h at 90 dBA."]'::jsonb, 0, 'The time left is the fraction remaining times the reference duration: 72.251817 percent of 4.000000 h is 2.890073 h, or 173.404361 minutes. Using the whole 4.000000 h ignores what the day has already used. Writing 2.890073 as minutes forgets the hours unit the reference duration carries.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 10, 'Why can the 173.404361 minutes at 95 dBA never be quoted on the OSHA action level?', '["The action level has a different reference duration at 95 dBA, which gives a longer time for the rest of the day.", "The action level is not a daily limit, so time left at a level has no meaning for it at any point in the day.", "On the action level the day has already used 72.054478 percent against a limit of 50, so nothing is left.", "The action level uses 16.61 only for the TWA, and the time left depends on the NIOSH coefficient of 10.0."]'::jsonb, 2, 'The time left belongs to one criterion. The same record has used 72.054478 percent of the action level, whose limit is 50 percent, so there is no remaining allowance on it. The two OSHA setups share a criterion level and a decibel exchange rate, so the reference duration at 95 dBA is 4.000000 h on both; it is the used share that differs.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 11, 'A supervisor asks for the time left at 85 dBA on the OSHA PEL after the OBEN day. What should the answer be?', '["16.000000 h times the 72.251817 percent that remains of the PEL.", "Unlimited, since 85 dBA gives a reference duration of 16.000000 h.", "173.404361 minutes, since the remaining share is the same at any level.", "The level is below the PEL threshold, so the question is not framed."]'::jsonb, 3, 'A level under the criterion''s threshold never uses PEL allowance, so it has no time left to compute, and the engine''s reference duration door reports it as below the threshold. Multiplying by the 16.000000 h OSHA reference duration at 85 dBA would describe the action level, which integrates from 80. The 173.404361 minutes belong to 95 dBA only.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 12, 'A download runs two shifts together and its periods total 25 hours. Which field does the engine name, and what does it report?', '["`periods[0].durationH`, the first period, since that is where the total is checked.", "`periods`, the record as a whole, and it reports no noise dose at all.", "`periods`, and it still reports the noise dose of all 25 hours beside a warning.", "No field at all: it reports the first 24 hours and warns that the rest was trimmed."]'::jsonb, 1, 'Judgement J4 refuses noise, LEX and chemical periods totalling over 24 hours, and the refused field is `periods`, the record taken as a whole. A refusal carries `error` and `field` in place of a result, so no noise dose is reported and no warning stands in for it. `periods[0].durationH` is the field for a negative first duration, which names one period rather than the record.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 13, 'At 80 dBA the NIOSH reference duration is 25.398417 h. Why does the engine accept that, when it refuses a record of 25 hours?', '["A reference duration describes an allowance; a record over 24 hours describes data no single day can hold.", "It does not accept it: any figure over 24 hours is refused wherever it appears in the engine.", "The NIOSH criterion has no day limit, while the OSHA criteria refuse anything over 24 hours.", "The reference duration is cut to 24 hours before it is used in any contribution."]'::jsonb, 0, 'A reference duration is how long the allowance would last at that level, and nobody has to work those hours: OSHA gives 32.000000 h at 80 dBA. The 24 hour refusal, judgement J4, is about the periods handed over as one day''s record. Nothing is rounded, and the limit is the same whatever the criterion.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 14, 'Your own sum of a download''s PEL contributions disagrees with the engine''s noise dose. What is the quickest way to find the cause?', '["Recompute the TWA with the exact coefficient and compare the two TWAs you get.", "Re-run the day on the NIOSH noise REL and take the lower of the two totals it gives.", "Round every reference duration to one decimal, as the published table prints them.", "Compare contributions period by period to find the row you read differently."]'::jsonb, 3, 'The engine returns each period''s contribution beside the total, so a disagreement points at the period that differs, and a missed period shows up as a gap of one whole contribution. The coefficient affects the TWA and never the noise dose. Another criterion gives a different answer to a different question, and rounding reference durations moves the last printed digit.'),
  ('hygiene', 'beginner', 'module', 'm04-reading-a-dosimeter-record', 15, 'On the OBEN day, how do the periods sort by sound level against by contribution?', '["Into the same order on every criterion.", "Into one order on OSHA, and a reversed one on NIOSH.", "Into different orders, on every criterion.", "Into the same order once quiet periods are dropped."]'::jsonb, 2, 'Sorting by level and sorting by contribution give two different orders on the OBEN day on every criterion: on the PEL the 99.100000 dBA period carries 8.827030 percent and the quieter 94.600000 dBA period 18.921153 percent. Dropping the periods below the threshold does not help, because that is exactly the PEL pair. The largest contribution is what a control should reach for first, and the maximum level is only one term.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 1, 'A planner asks which steady sound level would use exactly one day''s OSHA allowance in 3.000000 h. What does `noiseLevelForReferenceDurationDbA` answer?', '["89.245112 dBA, the NIOSH answer for the same 3 hours of work.", "97.075187 dBA, the reference duration formula run backwards.", "97.000000 dBA, the NIOSH level for half an hour.", "95.000000 dBA, the level giving a 4 hour reference duration on OSHA."]'::jsonb, 1, 'Solving T = 8 / 2^((L - 90)/5) for L at 3 hours gives 97.075187 dBA on OSHA. The tempting 89.245112 dBA is the NIOSH answer for the same hours, a stricter criterion. 97.000000 dBA is a NIOSH row for 0.500000 h, and 95.000000 dBA is the OSHA level for 4.000000 h, a longer allowance.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 2, 'The OSHA level for a 3.000000 h reference duration is 97.075187 dBA. What is the OSHA level for 6.000000 h?', '["87.075187 dBA, two 5 dB steps lower.", "95.000000 dBA, the OSHA level at 4 h.", "86.245112 dBA, the NIOSH level at 6 h.", "92.075187 dBA, one 5 dB step lower."]'::jsonb, 3, 'Every doubling of hours lowers the level by one decibel exchange rate, 5 dB on OSHA, so 97.075187 becomes 92.075187 dBA. Two steps, 87.075187 dBA, is the OSHA level for 12 hours, a second doubling. 95.000000 dBA belongs to 4 hours, and 86.245112 dBA is the NIOSH answer for 6 hours.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 3, 'At 85.000000 dBA the OSHA reference duration is 16.000000 h. What does a period at that sound level add on the OSHA PEL setup?', '["It adds nothing there, since the PEL counts only periods at 90 dBA or louder.", "It uses half of the PEL allowance for every 8 hours it lasts on the day.", "It is integrated at its 16.000000 h reference duration like any period.", "It is refused, because a reference duration over 8 hours is invalid."]'::jsonb, 0, 'The formula still returns the level and Table G-16a runs down to 80 dBA, but the PEL integrates nothing below 90, so a period at 85 dBA adds nothing there. It would be integrated by the action level, whose threshold is 80 dBA, at that 16.000000 h reference duration. Nothing is refused for a reference duration longer than a shift.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 4, 'Asked for the OSHA level at a quarter of an hour, the engine answers 115.000000 dBA. What does a still shorter time give?', '["The engine refuses, since no level above 115 dBA can ever be computed by it.", "The level stays at 115 dBA, since the formula is capped at Table G-16.", "The level rises past 115 dBA, above the highest level Table G-16 permits.", "The level falls again, since the formula reverses above a table top."]'::jsonb, 2, 'The formulas have no edge: a shorter time gives a higher level, past the 115 dBA of Table G-16. Under judgement J3 the engine warns above 115 and above 130 dBA and still computes, so nothing is capped or refused. The warning marks where the source stops, and the number rests on the formula alone beyond it.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 5, 'The level for a reference duration gives exactly 100 percent noise dose. What does that answer assume about the rest of the day?', '["That the worker has already used half the allowance before the task being planned begins.", "That the level is held for the whole of those hours and nothing else is on the day.", "That the day is 8 hours long, whatever reference duration the planner asked the engine for.", "That the rest of the day is spent quieter than the action level threshold of 80 dBA."]'::jsonb, 1, 'The answer is a level held steady for the stated hours with nothing else on the day. If part of the allowance is already used, the level for the remaining hours has to be lower, and the right question becomes the time left at a level. Quiet time below a threshold happens to add nothing, but the answer does not depend on assuming it.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 6, 'A report gives a TWA of 90 dBA and nothing else. What noise dose does `noiseDoseFromTwaPct` give for it on the NIOSH noise REL?', '["100.000000 percent.", "199.526231 percent.", "158.489319 percent.", "316.227766 percent."]'::jsonb, 3, 'On NIOSH, 90 dBA is five decibels above the criterion level of 85, so the noise dose is 100 times 10 to the power of 5 over 10.0, which is 316.227766 percent. The tempting 100.000000 percent is the OSHA answer, where 90 is the criterion level itself. 199.526231 and 158.489319 percent are the NIOSH figures at 88 and 87 dBA.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 7, 'On OSHA a TWA of 95 dBA gives 199.996999 percent, a hair short of 200. Why?', '["The printed 16.61 is a little larger than exact, so 5 dB buys slightly less than a doubling.", "The PEL threshold of 90 dBA removes a sliver of noise dose from every TWA above it.", "Table G-16a rounds the reference duration at 95 dBA, and the TWA inherits that error.", "At 95 dBA the engine switches to the exact coefficient, which falls short of a doubling."]'::jsonb, 0, 'With the exact coefficient one decibel exchange rate is exactly a doubling. The printed 16.61 sits slightly above exact, so dividing 5 dB by it gives a little less than log10 2 and the noise dose lands just under 200. That is judgement J1 seen from the other side. The threshold does not enter this door, and presets never switch coefficient.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 8, 'On NIOSH a TWA of 88 dBA gives 199.526231 percent, while on OSHA 95 dBA gives 199.996999. Why is the NIOSH figure further from 200?', '["The NIOSH scale has a lower criterion level, so its doublings are smaller.", "The NIOSH ceiling of 115 dBA compresses every noise dose on its scale.", "Its printed 10.0 sits further above the exact coefficient than 16.61 does.", "The 3 dB decibel exchange rate is always rounded before it is applied."]'::jsonb, 2, 'Both shortfalls come from a printed coefficient larger than exact. NIOSH''s 10.0 sits 0.034215715338 dB above its exact value and OSHA''s 16.61 only 0.000359525563 dB above, so the NIOSH doubling falls further short. The criterion level only shifts where 100 percent sits, and the ceiling is a warning on levels, never a change to the arithmetic.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 9, 'The OBEN NIOSH TWA of 89.242460 dBA is put back through `noiseDoseFromTwaPct` on the NIOSH noise REL. What comes back?', '["316.227766 percent, the noise dose at a TWA of 90 dBA.", "265.610944 percent, the noise dose it restates.", "72.054478 percent, the OSHA action level figure that day.", "100.000000 percent, since it is a daily TWA."]'::jsonb, 1, 'The two doors undo each other when the criterion is held fixed: 89.242460 dBA restates 265.610944 percent on NIOSH, just as 80.752126 dBA restates 27.748183 percent on the OSHA PEL. 316.227766 percent belongs to a TWA of exactly 90. 72.054478 percent is the OSHA action level noise dose of the same day, a different criterion.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 10, 'A colleague takes the OBEN NIOSH TWA of 89.242460 dBA and puts it into the OSHA formula to get an OSHA noise dose. What is wrong?', '["Nothing at all; a TWA is a sound level, so it can be read on any criterion you choose.", "Only the rounding: the TWA must first be taken to one decimal.", "The OSHA formula needs the TWA in minutes before the conversion.", "The TWA carries the NIOSH level and coefficient, so the result describes no record."]'::jsonb, 3, 'A TWA and its noise dose are one fact only while the criterion is fixed. A NIOSH TWA already has the 85 dBA criterion level and the 10.0 coefficient inside it, so feeding it to the OSHA formula mixes two criteria and gives a number that describes no record. To get the OSHA noise dose, run the periods on the OSHA criterion.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 11, 'What does one decibel on the TWA do to the noise dose on each criterion?', '["It multiplies the OSHA noise dose by 1.148695 and the NIOSH noise dose by 1.258925.", "It multiplies the OSHA noise dose by 1.258925 and the NIOSH noise dose by 1.148695.", "It adds about 1.148695 percent to the OSHA noise dose, whatever the starting TWA.", "It multiplies both noise doses by 2, since a decibel is one step of doubling."]'::jsonb, 0, 'The engine measures the ratio of the noise doses at two TWAs one decibel apart: 1.148695 on OSHA, where five decibels double the noise dose, and 1.258925 on NIOSH, where three do. The swapped pairing is the tempting slip. The effect is a ratio, the same at any TWA, and a doubling takes a full decibel exchange rate.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 12, 'A proposed control would take 3 dB off a TWA. Roughly what does that do to the noise dose on the NIOSH noise REL?', '["It cuts it by about a third, since three steps of 1.148695 compound to that factor.", "It cuts it by 3 percent, one percent for each decibel removed.", "It nearly halves it, since three steps of 1.258925 make close to a doubling.", "It halves it exactly, since 3 dB is one full NIOSH step and so an exact doubling."]'::jsonb, 2, 'One decibel multiplies the NIOSH noise dose by 1.258925, and three of those make a factor close to 2, so removing 3 dB nearly halves it. It is near and not exact because the printed 10.0 sits above the exact coefficient. 1.148695 is the OSHA ratio, and a decibel acts on the noise dose as a ratio and never as a fixed percentage.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 13, 'On the OSHA scale, what noise dose does a TWA of 92 dBA restate?', '["501.187234 percent.", "131.949999 percent.", "100.000000 percent.", "199.996999 percent."]'::jsonb, 1, 'D = 100 x 10^((92 - 90)/16.61) gives 131.949999 percent on OSHA. 501.187234 percent is the NIOSH figure at the same TWA, because the NIOSH criterion level is lower and its steps steeper. 100.000000 percent is the OSHA value at 90 dBA and 199.996999 percent at 95 dBA.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 14, 'Which published table covers a noise dose from 10.000000 to 999.000000 percent in 150 rows?', '["OSHA Table A-1, noise dose to TWA.", "NIOSH Table 1-2, noise dose to TWA.", "OSHA Table G-16a, level to hours.", "NIOSH Table 1-1, level to hours."]'::jsonb, 0, 'OSHA Table A-1 runs from 10.000000 to 999.000000 percent in 150 rows. NIOSH Table 1-2 converts the same kind of quantity over 83 rows from 20.000000 to 10000000.000000 percent. Tables G-16a and 1-1 tabulate the reference duration by level, so they cover no noise dose range at all.'),
  ('hygiene', 'beginner', 'module', 'm05-inverse-questions', 15, 'A 132 dBA period is integrated on the OSHA PEL setup. What does the engine say about the number it returns for that level?', '["It refuses the level on `levelDbA`, since no table covers 132 dBA.", "It caps the period at 130 dBA and integrates it at that level.", "It reports nothing, since the noise dose is still under 100 percent.", "It warns the formula is extrapolated past 130 dBA, the top of Table G-16a."]'::jsonb, 3, 'The engine''s own words are "a level of 132 dBA is above 130 dBA, the top of Table G-16a: the formula is extrapolated there", and the period is still integrated under judgement J3, giving 84.448506 percent with 2 warnings. Past the top of a table there is no printed row to check against, so the number rests on the formula alone. Nothing is capped or refused.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 1, 'Walking a dosimeter record from download to report, which step comes first?', '["Add the contributions, since the total is what every criterion reports.", "Restate the TWA, since the percentage is easier to read as a level.", "Name the criterion, since it sets the threshold and every reference duration.", "Find the loudest period, since it decides the noise dose of the whole day on any criterion."]'::jsonb, 2, 'Naming the criterion first is the habit that makes the rest mean something: it decides which periods pass the threshold and what each reference duration is. On the OBEN day, changing it alone moves the noise dose from 27.748183 to 72.054478 or 265.610944 percent. The loudest period is one term in the sum and decides nothing on its own.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 2, 'A draft report gives the OBEN day''s NIOSH figure of 265.610944 percent with the acronym unqualified and a closing verdict word. Which rewrite follows this course''s rules?', '["The noise dose on the NIOSH noise REL was 265.610944 percent, against a limit noise dose of 100 percent.", "The NIOSH noise REL figure was 265.610944 percent, so the worker''s noise exposure fails on that day.", "The NIOSH noise dose was 265.610944 percent, which is over the limit on that criterion''s scale.", "The noise exposure was 89.242460 dBA on the NIOSH noise REL, which is over the limit and fails."]'::jsonb, 0, 'Digest section 24 requires "noise dose", a qualified noise exposure and "NIOSH noise REL" written in full, and the course never grades a verdict word: a comparison names the criterion and its limit noise dose in the same sentence. The rewrite ending in "fails" still closes on a bare verdict, and the one saying "NIOSH noise dose" names only the agency, which leaves open which NIOSH limit is meant. The one in dBA swaps the noise dose for its TWA and keeps the verdict.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 3, 'The same three letters name two different NIOSH limits in this course. How must each be written?', '["As the bare acronym, once the tier makes plain which is meant.", "As the agency and acronym alone, since NIOSH publishes both.", "With the qualifier on first use only, and bare after that.", "As \"NIOSH noise REL\" or \"NIOSH heat REL\", every time."]'::jsonb, 3, 'Digest section 24 legislates it: the NIOSH recommended exposure limit for noise in this tier and the NIOSH recommended exposure limit for heat stress in the Expert tier share an acronym, so the qualifier goes in every time. Naming the agency alone leaves the limit ambiguous, which is the whole problem, and a reader may open any page without the first use in view.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 4, 'Why does this course write "decibel exchange rate" in full?', '["Because OSHA''s text defines it only under that full name in Appendix A.", "Because the Economics courses use \"exchange rate\" for currency.", "Because a bare rate could be read as a sampling frequency on the instrument.", "Because the engine refuses the field name `exchangeRateDb`."]'::jsonb, 1, 'Digest section 24, rule 4: the words already mean a currency rate in the Economics courses, so this course always writes "decibel exchange rate" or "an exchange rate of 5 dB". It is a rule about readers arriving from other courses. `exchangeRateDb` is a valid engine field, refused only when it is not a finite number of dB above zero.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 5, 'Why does this course call a reading from a sound level meter a sound level?', '["Other courses use noise for scatter in data, so the word is kept for noise exposure.", "OSHA''s Appendix A has no other word for a reading taken by an instrument.", "The engine refuses any input field whose name refers to noise directly.", "A sound level is a percentage of an allowance, while a reading is in dBA."]'::jsonb, 0, 'Digest section 24, rule 3: noise already means scatter in data in the Decline Curve Analysis, Well Test and Seismolord courses, so a reading is a sound level and noise exposure is kept for a noise dose. It is a rule about readers arriving from other courses. A sound level is in dBA; the percentage of an allowance is the noise dose.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 6, 'The capstone TWAs are graded on which coefficient, and why?', '["The exact ones, since a graded answer must use the most precise values.", "Either, since the two land within the grading tolerance on both scales.", "The exact one on NIOSH and the printed one on OSHA, where tables agree.", "The printed ones, 16.61 and 10.0, as judgement J1 has each preset use."]'::jsonb, 3, 'The TWAs are graded on the coefficient each source prints: 16.61 on OSHA, as the mandatory Appendix A text writes it, and 10.0 on NIOSH. A TWA worked with the exact coefficient will disagree, and the digest measures how far: eight hours at a constant 100 dBA on the NIOSH preset gives 100.051500 dBA where the exact coefficient gives 100.000000. That is judgement J1, the same rule the engine''s presets follow.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 7, 'To how many decimals does this course print a sound level, a noise dose or a duration?', '["One decimal, the precision at which OSHA Table A-1 and Table G-16a print their own rows.", "Twelve throughout, the precision the constants of digest section 3 carry.", "Six, while a measured constant prints to twelve and a count is a whole number.", "Two, as the printed coefficients 16.61 and 10.0 are written."]'::jsonb, 2, 'The digest''s precision rule: sound levels in dBA, noise doses and percentages, durations in hours and in minutes, concentrations, indices, temperatures and metabolic rates print to six decimals, measured constants print to twelve and counts are whole numbers. One decimal is what the published tables print, which is a property of the sources. Twelve belongs to the measured constants alone, such as the PEL threshold at 90.000000000000 dBA.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 8, 'Why can judgement J2, the inclusive threshold, never decide a graded capstone answer?', '["Because the capstone only uses the OSHA PEL criterion.", "Because no capstone input sits exactly on a threshold.", "Because the capstone rounds every level to whole decibels.", "Because J2 applies only to NIOSH and never to OSHA."]'::jsonb, 1, 'Digest section 23: the judgement calls are taught by name and never tested at their boundary, and no capstone input sits on a threshold. The rule still matters for real records, which do put periods on the line. The eighteen graded fields of this course include LEX values and chemical averages, so no capstone rests on the OSHA PEL alone, and levels are stated to six decimals, such as the 84.300000 dBA of the first OBEN period.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 9, 'Which of these is never graded in this course, in any tier?', '["A verdict word such as exceeds or passes, standing for the number.", "The TWA of a noise dose on a named criterion, worked from its printed formula.", "The noise dose of a record on the OSHA action level, in percent.", "The LEX,8h of a day of tasks, in dBA, which the next tier adds."]'::jsonb, 0, 'Digest section 23 lists any verdict word, exceeds, passes or at or above an action value, among the things never graded, because a verdict means nothing without its criterion and the same record gives different verdicts on different criteria. The other three name quantities the digest counts among the eighteen graded fields of this course: noise doses and TWAs, LEX values, a protector estimate, chemical averages and indices, reduction-factor arithmetic and two one-hour averages.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 10, 'A site manager asks for the OBEN worker''s ACGIH noise limit to set beside the figures. What does this course do?', '["It quotes the ACGIH value from the engine''s own table of licensed limits.", "It uses the NIOSH noise REL, since ACGIH and NIOSH publish the same values.", "It asks the engine for the preset ''ACGIH'', which returns the licensed limit.", "It never quotes one, since ACGIH values are licensed and every limit is an input."]'::jsonb, 3, 'Digest section 25: ACGIH TLVs, ISO 9612 and ISO 7243 text are licensed and never quoted, the engine embeds no limit table, and every limit is typed as an input from a public OSHA or NIOSH value. Asking for the preset ''ACGIH'' is refused on `criterion`. Claiming two bodies publish the same value is itself a licensed claim this course does not make.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 11, 'Four subjects sit beside this course and are owned elsewhere. What does this course do with them?', '["It teaches each of them briefly, so that a single report can cover the whole workplace.", "It converts each into a noise exposure figure the engine can then integrate.", "It cites the owner and stops, since each is a different quantity from a noise dose.", "It refers them to the Expert tier, where every seam is taught in full."]'::jsonb, 2, 'Digest section 25 says to cite and to stop. A radiant flux in kW/m2, an emission from a glycol unit, a rate per hours worked and a matrix of likelihood and consequence are each a different quantity from a noise dose, measured a different way, so this course names the owner beside the figure and computes nothing. No tier of it teaches them, and the engine offers no conversion between them.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 12, 'Rule 1 of digest section 24 keeps one word from standing on its own here. Which word, and who else claims it?', '["The word for a reading from a meter, claimed by three other courses of the academy.", "The shorter word for a noise dose, claimed by Flow Assurance and Gas Processing.", "The acronym two different NIOSH limits share, which carries a qualifier of its own.", "The words for a decibel exchange rate, claimed by the Economics courses."]'::jsonb, 1, 'Digest section 24, rule 1: this course writes "noise dose" on first use in every lesson and every bank question and never the shorter word on its own in a prompt, an option or a heading, because that word already belongs to inhibitor and methanol work in the Flow Assurance and Gas Processing courses. The reading, the acronym and the decibel exchange rate are rules 3, 4 and the two misreadings that close the section, each a different collision.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 13, 'A question asks for an octave-band protector estimate or an ISO 9612 uncertainty budget. What is the honest answer from this engine?', '["It has no door for either, so this engine does not compute them.", "It computes both through `hearingProtectorEstimate` with a method name.", "It computes them after the noise dose, from the day''s contributions.", "It computes them only on the NIOSH noise REL."]'::jsonb, 0, 'Digest section 1 lists what the engine does not provide and says so by having no door: spectral (octave-band) protector methods, ISO 9612 uncertainty budgets, ISO 7243 adjustments and any licensed limit table. `hearingProtectorEstimate` takes a named method from a fixed list, and none of them is spectral.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 14, 'A reading taken on the C-weighting is typed into a report. How should it be written?', '["In dBA, since every level in this course is written that way.", "In dBA after adding 7 dB, the Appendix B A-weighted step.", "As a noise dose, since the weighting drops out in percent.", "In dBC, since it is a different weighting from dBA."]'::jsonb, 3, 'Digest section 25: levels are in dBA unless a row says dBC, and a level read in dBC is a different weighting that must never be written as dBA. Adding a fixed step to turn one weighting into the other is no conversion this tier teaches, and a noise dose is built from A-weighted levels.'),
  ('hygiene', 'beginner', 'module', 'm06-the-associate-capstone', 15, 'A report of the OBEN day on the OSHA PEL lists each period''s contribution. What does that list let a reader see that the total alone cannot?', '["That the day''s noise dose would pass on every criterion it was read on.", "That the TWA was computed with the exact coefficient throughout.", "That the 94.600000 dBA period carries more than the 99.100000 dBA one.", "That every period on the record was above the 90 dBA PEL threshold."]'::jsonb, 2, 'Listing contributions shows where the percentage came from: 18.921153 percent from the 94.600000 dBA period and 8.827030 percent from the louder 99.100000 dBA one. A reader can check the arithmetic in a minute. Four of the six periods sit below the PEL threshold, and the same day is over two other criteria.'),
  ('hygiene', 'beginner', 'final', null, 1, 'At 81.000000 dBA the engine gives an OSHA reference duration of 27.857618 h, and Table G-16a prints 27.900000 h. Which figure does T = 8 / 2^((L - 90)/5) reproduce?', '["27.900000 h; the engine rounds its own answer down to three decimals.", "Neither; the row at 81 dBA is an erratum the formula refutes outright.", "27.857618 h; the printed row is that figure rounded to one decimal.", "27.900000 h; the formula is only exact at whole steps of 5 dB like 85."]'::jsonb, 2, 'Putting 81 into the formula gives 27.857618 h, and one decimal of that is the printed 27.900000, 0.042382 h away and inside its printed tolerance. The printed row is the rounding and the engine''s figure is the formula. The formula holds at every level, and the one refuted printed row in these tables is on NIOSH Table 1-1.'),
  ('hygiene', 'beginner', 'final', null, 2, 'What reference duration does NIOSH Table 1-1 give at 91.000000 dBA?', '["2.000000 h, which is 120.000000 minutes.", "6.964405 h, the OSHA figure at that level.", "2.519842 h, the NIOSH figure at 90 dBA.", "1.587401 h, the NIOSH figure at 92 dBA."]'::jsonb, 0, '91 dBA is two 3 dB steps above the 85 dBA criterion level, so 8 hours halves twice to 2.000000 h, printed as 120.000000 minutes. The tempting 6.964405 h is the OSHA reference duration at 91 dBA, a different criterion. The 90 and 92 dBA rows sit either side of the answer on the same NIOSH ladder.'),
  ('hygiene', 'beginner', 'final', null, 3, 'At 94.000000 dBA the OSHA reference duration is 4.594793 h and the NIOSH one is 1.000000 h. What does that say about a reference duration?', '["One of the two figures must be a transcription slip in its table.", "NIOSH measures the reference duration in minutes and OSHA in hours.", "The instrument reads 94 dBA differently under the two criteria.", "It belongs to the criterion as much as to the sound level."]'::jsonb, 3, 'The same level gives two reference durations because the criteria differ in criterion level and decibel exchange rate. Both figures are reproduced from their published tables. NIOSH Table 1-1 prints hours, minutes and seconds and the golden stores hours, so the unit is no explanation, and the sound level itself is one reading.'),
  ('hygiene', 'beginner', 'final', null, 4, 'The ORONI record has 3.000000 h at 80.000000 dBA. What does that period add to the OSHA action level noise dose?', '["11.811760 percent, which is the NIOSH noise REL share of the period.", "9.375000 percent, 3 hours over a 32.000000 h reference duration.", "Nothing, since 80 dBA sits on the threshold and is left out of it.", "25.000000 percent, the share of the 90 dBA period on the same record."]'::jsonb, 1, 'At 80 dBA the OSHA allowance lasts 32.000000 h, so three hours use 9.375000 percent of it. A level exactly on the action level''s line is counted, which is the rule the ORONI record exists to show. The NIOSH allowance at the same level lasts 25.398417 h, which is where the larger 11.811760 percent comes from, and 25.000000 percent belongs to the 90 dBA period.'),
  ('hygiene', 'beginner', 'final', null, 5, 'ORONI read against the OSHA hearing conservation trigger: which pair of figures comes back?', '["34.375000 percent and 82.296991 dBA.", "25.000000 percent and 79.999784 dBA.", "91.181812 percent and 84.599082 dBA.", "34.375000 percent and 84.599082 dBA."]'::jsonb, 0, 'The action level integrates the 80 dBA and 90 dBA periods, 9.375000 plus 25.000000 percent, which is 34.375000 percent and restates as 82.296991 dBA. The 25.000000 percent and 79.999784 dBA pair is the PEL, which integrates only the 90 dBA period. 91.181812 percent and 84.599082 dBA are the NIOSH noise REL figures of the same record.'),
  ('hygiene', 'beginner', 'final', null, 6, 'A hand-typed criterion arrives with no criterion level. What does the engine return?', '["A reference duration computed on a default criterion level of 90 dBA, the OSHA figure.", "A refusal on `criterion`, since the name of the preset is then unknown.", "A refusal on `criterionLevelDbA`: \"criterionLevelDbA must be a finite number of dBA\".", "A reference duration on the NIOSH criterion level of 85 dBA instead."]'::jsonb, 2, 'The golden case ref-criterion-missing refuses on `criterionLevelDbA` with the message quoted in the key, in the engine''s own words. A criterion typed by hand must carry a usable criterion level, and the engine supplies no default. The `criterion` field is refused for an unknown preset name, which is a different mistake.'),
  ('hygiene', 'beginner', 'final', null, 7, 'A download''s second period has no sound level recorded. Which field does the engine refuse?', '["`periods[0].levelDbA`, the first period.", "`periods`, the record taken as a whole.", "`levelDbA`, with no period named at all.", "`periods[1].levelDbA`, the second period."]'::jsonb, 3, 'The golden case dose-missing-level refuses on `periods[1].levelDbA` with "periods[1].levelDbA must be a finite number". Positions count from zero, so index 1 is the second period. The field names the row so a hygienist can go straight to it; `periods` is kept for faults in the record as a whole.'),
  ('hygiene', 'beginner', 'final', null, 8, 'What does `noiseDose` return when it is handed an empty list of periods?', '["A noise dose of 0.000000 percent with a TWA of null for the day.", "A refusal on `periods`: \"periods must be a non-empty array\".", "A refusal on `dosePct`, since there is no noise dose to restate.", "A warning that the record is empty, and a zero TWA."]'::jsonb, 1, 'The golden case dose-empty refuses on `periods` with the message in the key. A noise dose of zero with a null TWA is what a real record with nothing above the threshold returns, which is a legitimate day with periods in it. `dosePct` is the field of the TWA door, and the engine does not return a TWA of zero.'),
  ('hygiene', 'beginner', 'final', null, 9, 'How many functions and frozen tables does the engine behind this course export?', '["3 functions, one for each criterion this tier reads the record against.", "57 functions, one for each of the refusal cases the vendored golden carries.", "26 functions and 8 frozen tables, each result naming its criterion or source.", "26 functions and a licensed limit table for every criterion in use."]'::jsonb, 2, 'Digest section 1: the engine exports 26 functions and 8 frozen tables, and every result names the criterion or source it was computed against. 57 is the number of refusal cases in the golden. The engine embeds no limit table of its own; every exposure limit is an input.'),
  ('hygiene', 'beginner', 'final', null, 10, 'ORONI''s OSHA PEL noise dose of 25.000000 percent restates as a TWA of 79.999784 dBA. Why is that a hair under 80?', '["Two halvings with 16.61 fall a whisker short; the exact coefficient lands on 80.000000.", "The 90 dBA period sits on the threshold and is counted at slightly less than full weight.", "The engine subtracts the threshold of 90 dBA before it takes the logarithm.", "The ORONI record is 8.000000 h long, and a TWA always uses a 9 hour normaliser."]'::jsonb, 0, 'Table A-1''s 25 percent row gives 79.999784 dBA with 16.61 and 80.000000 dBA with the exact coefficient, and prints 80.000000. A quarter of the allowance is two halvings, so the TWA is two decibel exchange rates below 90 with the exact coefficient and a whisker lower with the printed one. J2 counts the threshold period in full.'),
  ('hygiene', 'beginner', 'final', null, 11, 'Just past one full allowance, at 105.000000 percent, OSHA prints 90.400000 dBA. The printed coefficient gives 90.351954 and the exact one 90.351947. Is that entry evidence for either?', '["That 16.61 is right, since its figure is the larger one.", "That the exact coefficient is right, since it is smaller.", "That the table is in error, being 0.048053 dB too high.", "Nothing between the two: both round to the printed figure."]'::jsonb, 3, 'Rounded to one decimal both engine columns give the printed 90.400000 dBA, so the row is consistent with either coefficient, as all 150 rows of Table A-1 are. The gap between the two is in the sixth decimal. The printed figure sits 0.048053 dB above the exact column, which is ordinary one-decimal rounding and inside its tolerance.'),
  ('hygiene', 'beginner', 'final', null, 12, 'At the low end of NIOSH''s noise dose table, 20.000000 percent is printed as 78.000000 dBA; 10.0 gives 78.010300 and the exact coefficient 78.034216. Can this entry tell the two apart?', '["It rejects the exact coefficient, since 78.034216 is further from the print.", "It cannot tell the two coefficients apart, since both round to 78.000000.", "It rejects 10.0, since the printed figure sits below both of the columns.", "It is an erratum, since neither column matches the printed figure exactly."]'::jsonb, 1, 'Both columns round to the printed one decimal, so this row is among those of Table 1-2 that do not separate the coefficients; 49 of its 83 rows do. Being further from the print decides nothing inside the table''s rounding. Neither column is meant to match to six decimals, because the table prints one.'),
  ('hygiene', 'beginner', 'final', null, 13, 'For 700000.000000 percent the printed NIOSH figure is 123.500000 dBA. With 10.0 the engine reaches 123.450980, and with the exact coefficient 123.319418. Which coefficient survives?', '["The exact one, since it is the more precise value of the two.", "Neither, since both columns miss the printed figure by a margin.", "10.0, since only its column rounds to the printed figure.", "Both alike, since the two columns differ by only one decimal."]'::jsonb, 2, 'At one decimal 123.450980 rounds to the printed 123.500000 and 123.319418 does not, so the row rejects the exact coefficient and supports 10.0. That is judgement J1 made visible: at a noise dose that large, the 0.034215715338 dB gap in the coefficient is multiplied by a big logarithm and moves the printed decimal.'),
  ('hygiene', 'beginner', 'final', null, 14, 'How does the engine measure the TWA coefficient each preset carries?', '["It asks for the TWA of a 1000 percent noise dose and subtracts the criterion level.", "It reads the coefficient from the source text and stores it without ever checking it.", "It fits a line through the rows of Table A-1 and takes the slope of that fitted line.", "It asks for the level giving a 4 hour reference duration and divides by log10 2."]'::jsonb, 0, 'Digest section 3: the coefficient is measured as the TWA of a 1000 percent noise dose less the criterion level, since log10 of 10 is one. That returns 16.610000000000 for both OSHA presets and 10.000000000000 for NIOSH, each pinned against a literal. The 4 hour question measures the decibel exchange rate.'),
  ('hygiene', 'beginner', 'final', null, 15, 'What TWA does the last row of OSHA Table A-1, a noise dose of 999.000000 percent, give with 16.61?', '["105.000325 dBA.", "134.030900 dBA.", "106.602423 dBA.", "106.602783 dBA."]'::jsonb, 3, 'The engine gives 106.602783 dBA at 999.000000 percent with the printed coefficient, and the table prints 106.600000. 106.602423 dBA is the same row with the exact coefficient. 105.000325 dBA is the 800.000000 percent row, and 134.030900 dBA belongs to NIOSH Table 1-2 at 8000000.000000 percent.'),
  ('hygiene', 'beginner', 'final', null, 16, 'On NIOSH Table 1-2 a noise dose of 200.000000 percent gives 88.010300 dBA with 10.0. What does doubling the noise dose do to a NIOSH TWA?', '["It adds 5 dB, as a doubling does on the OSHA scale.", "It adds about one decibel exchange rate, 3 dB.", "It doubles the TWA, from 85 to 170 dBA.", "It adds 10 dB, the size of the coefficient."]'::jsonb, 1, 'Doubling adds the coefficient times log10 2, which is the decibel exchange rate: exactly 3 dB with the exact coefficient, giving 88.000000, and slightly more with 10.0, giving 88.010300 dBA. 5 dB is the OSHA step. A TWA is a logarithm of the noise dose, so doubling the noise dose never doubles the level.'),
  ('hygiene', 'beginner', 'final', null, 17, 'Handed a noise dose below zero, what does the engine''s TWA door do?', '["A negative TWA, below the criterion''s threshold of integration.", "The TWA of the absolute value of the noise dose, sign dropped.", "The same refusal on `dosePct` a noise dose of zero gets.", "A null TWA with a warning, as `noiseDose` gives."]'::jsonb, 2, 'Golden case twa-dose-negative: the door refuses on `dosePct` and reuses the zero message word for word, since below zero is as impossible as zero for a logarithm. Dropping the sign would repair the input silently, which the engine never does. A null TWA is what `noiseDose` reports for a day with nothing integrated, a different door.'),
  ('hygiene', 'beginner', 'final', null, 18, 'The NIOSH noise REL limit noise dose is measured at 100.000000000001 percent. Why not exactly 100?', '["It is found by bisection on `exceedsLimit`, and the literal is 100.", "NIOSH publishes its limit a trillionth above 100 on purpose.", "The printed 10.0 adds that excess to every limit it touches.", "It is rounded up from the NIOSH ceiling of 115 dBA each time."]'::jsonb, 0, 'Digest section 3 measures each limit noise dose by bisecting on `exceedsLimit` over one 8 hour period, so the measured figure carries the bisection''s last-place error. The literal it is pinned against is 100.000000000000 and the relative difference is 6.679e-15. The coefficient affects TWAs and never the limit, and the ceiling is a level.'),
  ('hygiene', 'beginner', 'final', null, 19, 'Which measurement pins the PEL threshold at 90.000000000000 dBA and the other two at 80.000000000000?', '["By reading the lowest row of the table.", "By subtracting 10 dB from the criterion level.", "By bisecting on the `exceedsLimit` flag.", "By bisecting on its `belowThreshold` flag."]'::jsonb, 3, 'Digest section 3: thresholds are bisected on `belowThreshold`, giving 90.000000000000 dBA for the PEL and 80.000000000000 for the action level and the NIOSH noise REL. Subtracting 10 dB would give 80 on the PEL, which is wrong. `exceedsLimit` is the flag bisected for the limit noise dose.'),
  ('hygiene', 'beginner', 'final', null, 20, 'One period at 117 dBA, scored against NIOSH''s recommendation: which figures and warning count come back?', '["52.780316 percent and 85.390260 dBA, with 1 warning.", "2156.290550 percent and 98.337073 dBA, with 1 warning.", "13083.161045 percent and 106.167127 dBA, with 2 warnings.", "A refusal, since the level is above the 115 dBA ceiling."]'::jsonb, 1, 'At 117 dBA NIOSH gives 2156.290550 percent and a TWA of 98.337073 dBA, with the single ceiling warning, and still integrates under judgement J3. 52.780316 percent is the same period on the OSHA PEL. 13083.161045 percent is the 132 dBA period on NIOSH, which also passes the top of Table G-16a and so carries 2 warnings.'),
  ('hygiene', 'beginner', 'final', null, 21, 'The engine exports `OSHA_TABLE_G16A_MAX_DBA` and `OSHA_TABLE_G16_MAX_DBA`. What are they?', '["115 marks where Table G-16a ends; 130 is Table G-16''s maximum permitted level.", "130 and 115, the ceilings of the NIOSH noise REL and of the OSHA PEL.", "130 marks where Table G-16a ends; 115 is Table G-16''s maximum permitted level.", "90 and 80, the PEL threshold and the action level threshold in dBA."]'::jsonb, 2, 'Digest section 8: `OSHA_TABLE_G16A_MAX_DBA` is 130 and `OSHA_TABLE_G16_MAX_DBA` is 115. The swapped pairing is the tempting slip; above 130 the warning says the formula is extrapolated, and above 115 it says the level is above anything Table G-16 permits. The NIOSH ceiling of 115 dBA is a separate warning on the NIOSH noise REL preset.'),
  ('hygiene', 'beginner', 'final', null, 22, 'ORONI''s OSHA action level TWA is 82.296991 dBA, under 85. Which noise dose comparison says the same thing?', '["34.375000 percent against 100 percent, the limit noise dose of the PEL.", "25.000000 percent against 50 percent, taking the PEL''s noise dose of that day.", "91.181812 percent against 100 percent, the NIOSH noise REL reading of the day.", "34.375000 percent against the action level limit noise dose of 50 percent."]'::jsonb, 3, 'A TWA and its noise dose restate one sum on one criterion, so the action level TWA under 85 dBA pairs with the action level noise dose under its own limit of 50 percent; section 1910.95(c)(1) makes a TWA of 85 and half a noise dose the same line. 100 percent is the PEL''s limit, 25.000000 percent is the PEL''s noise dose from a stricter threshold, and 91.181812 percent belongs to NIOSH.'),
  ('hygiene', 'beginner', 'final', null, 23, 'Where does the NIOSH noise REL criterion come from, and what kind of document is it?', '["NIOSH 98-126 (1998), a criteria document recommending a standard.", "29 CFR 1910.95 Appendix A, a mandatory regulation from OSHA.", "HSE L108, the UK guidance on the Control of Noise at Work Regulations.", "A licensed limit table that the engine keeps for this preset."]'::jsonb, 0, 'Digest section 1 names the source: NIOSH 98-126 Criteria for a Recommended Standard: Occupational Noise Exposure (1998), section 1.1 and Appendix. It is a recommendation rather than a regulation. 1910.95 Appendix A is the OSHA text that writes 16.61, and the engine embeds no licensed limit table.'),
  ('hygiene', 'beginner', 'final', null, 24, 'The three OBEN TWAs, 80.752126, 87.635749 and 89.242460 dBA, sit much closer together than the three noise doses. Why is it wrong to read them as three estimates of one sound level?', '["They are three estimates of one sound level, and their mean is the best figure.", "Each restates its own noise dose on its own criterion; the log only compresses them.", "The NIOSH TWA is the true level, and the two OSHA TWAs are rounded versions of it.", "The TWAs differ only because the three criteria use different decibel meters."]'::jsonb, 1, 'The logarithm compresses the percentages, so the TWAs look close, but each is its own noise dose restated against its own criterion level with its own coefficient. There is no shared quantity for them to estimate, so averaging them means nothing. The instrument record is one and the same in all three.'),
  ('hygiene', 'beginner', 'final', null, 25, 'Which document writes TWA = 16.61 log10(D/100) + 90 and sets the OSHA PEL setup?', '["NIOSH 98-126, the criteria document from 1998.", "OSHA Table G-16a, the table of reference hours.", "29 CFR 1910.95 Appendix A, the mandatory text.", "The OSHA Technical Manual chapter on protectors."]'::jsonb, 2, 'Digest section 5: the mandatory Appendix A of 29 CFR 1910.95 writes the formula with 16.61, and the engine uses the coefficient the regulation writes. NIOSH 98-126 is the source of the NIOSH noise REL with 10.0. Table G-16a tabulates reference durations and holds no TWA formula.'),
  ('hygiene', 'beginner', 'final', null, 26, 'The fifth OBEN period lasts 0.200000 h and its NIOSH reference duration at 99.100000 dBA is 0.307786 h. What does it contribute on the NIOSH noise REL?', '["8.827030 percent.", "91.895868 percent.", "27.646683 percent.", "64.980192 percent."]'::jsonb, 3, '0.200000 over 0.307786 h is 64.980192 percent of the NIOSH allowance. 8.827030 percent is the same period on OSHA, where its reference duration is 2.265768 h. 91.895868 and 27.646683 percent are the NIOSH contributions of the 94.600000 and 84.300000 dBA periods.'),
  ('hygiene', 'beginner', 'final', null, 27, 'On the NIOSH noise REL, which OBEN period should a control target first to lower the day''s figure most?', '["The 94.600000 dBA period, which carries 91.895868 percent.", "The 99.100000 dBA period, since it is the loudest one.", "The 84.300000 dBA period, since it lasts 2.600000 h.", "The 81.200000 dBA period, which carries 9.091664 percent."]'::jsonb, 0, 'The largest contribution is the one a control should reach for first, and on NIOSH that is the third period at 91.895868 percent. The loudest period carries 64.980192 percent and the longest integrated one 27.646683 percent. A control aimed at the 81.200000 dBA period would barely move the total.'),
  ('hygiene', 'beginner', 'final', null, 28, 'Judgement J4 refuses periods that total more than 24 hours. Which records does it cover?', '["Noise dosimeter records alone, and nothing else.", "Noise, LEX and chemical records alike.", "Only records on the OSHA presets, PEL and action level.", "Only records with a period over 8 h."]'::jsonb, 1, 'Digest section 1: noise, LEX and chemical periods totalling over 24 hours are refused, on the field `periods`. The rule is about the data being one day, so it does not depend on the criterion or on any single period''s length; a shift longer than 8 hours that fits in a day is accepted.'),
  ('hygiene', 'beginner', 'final', null, 29, 'A worker spends exactly the 173.404361 minutes left at 95 dBA after the OBEN day. Where does the OSHA PEL noise dose then stand?', '["At 72.251817 percent, the share that remained.", "At 50 percent, the action level''s limit reached.", "At 100 percent, the whole allowance used exactly.", "At 173.404361 percent, the minutes read as a share."]'::jsonb, 2, 'The time left is defined as the fraction remaining times the reference duration, so spending all of it adds exactly the 72.251817 percent that remained to the day''s 27.748183 percent, which is 100 percent. 72.251817 percent is the addition alone, and 173.404361 is a count of minutes. 50 percent belongs to the action level, a different criterion with its own limit.'),
  ('hygiene', 'beginner', 'final', null, 30, 'After the OBEN day, how does the time left at 90 dBA on the OSHA PEL compare with the 173.404361 minutes at 95 dBA?', '["It is the same, since the share left is the same at any level.", "It is half as long, since 90 dBA is the PEL''s criterion level.", "It is zero, since 90 dBA is below the PEL threshold of 90 dBA.", "It is twice as long, since the reference duration is 8.000000 h."]'::jsonb, 3, 'The time left is the remaining share times the reference duration, and at 90 dBA the OSHA reference duration is 8.000000 h, twice the 4.000000 h at 95 dBA, so the same share buys twice the time. The PEL threshold is inclusive under J2, so 90 dBA is integrated and has time left to compute.'),
  ('hygiene', 'beginner', 'final', null, 31, 'How many of the six OBEN periods does the NIOSH noise REL integrate, and which stays out?', '["5 of the 6, with only the 76.500000 dBA period left out.", "All 6, since the NIOSH threshold of 80 dBA is the lowest of the three criteria.", "2 of the 6, the same pair of periods the OSHA PEL setup integrates.", "5 of the 6, with the 81.200000 dBA period left out for being under 85 dBA."]'::jsonb, 0, 'Digest section 6 counts them: the PEL setup integrates 2 of the 6 periods, the action level 5 and the NIOSH noise REL 5. The NIOSH threshold is 80 dBA, so the 81.200000 dBA period is integrated and carries 9.091664 percent, and only the 76.500000 dBA period falls under every threshold in this tier. The criterion level of 85 dBA sets the allowance and never decides what counts.'),
  ('hygiene', 'beginner', 'final', null, 32, 'One day holds a single period of 16.000000 h at 85 dBA. What share of an allowance does it use on the OSHA action level, and does the engine accept it?', '["50 percent of one allowance, and yes, since the action level is half.", "100 percent of one allowance, and yes, since it fits inside 24 hours.", "Nothing, and yes, since 85 dBA is below the action level threshold.", "100 percent of one allowance, but no, since it runs past 8 hours."]'::jsonb, 1, 'The OSHA reference duration at 85 dBA is 16.000000 h, so 16 hours there uses exactly one allowance, and the action level''s threshold of 80 dBA lets the period in. A shift longer than 8 hours that fits inside a day is accepted; only records over 24 hours are refused. The action level halves the limit and moves no share.'),
  ('hygiene', 'beginner', 'final', null, 33, 'Which sound levels give exactly 100 percent noise dose in 12.000000 h?', '["92.075187 dBA on OSHA and 86.245112 dBA on NIOSH.", "85.000000 dBA on OSHA and 82.000000 dBA on NIOSH.", "87.075187 dBA on OSHA and 83.245112 dBA on NIOSH.", "83.245112 dBA on OSHA and 87.075187 dBA on NIOSH."]'::jsonb, 2, 'The engine''s `noiseLevelForReferenceDurationDbA` gives 87.075187 dBA on OSHA and 83.245112 dBA on NIOSH for 12 hours. The 6 hour row is 92.075187 and 86.245112, and the 16 hour row is 85.000000 and 82.000000. The swapped pair gets the order wrong, since NIOSH gives the lower level at every duration.'),
  ('hygiene', 'beginner', 'final', null, 34, 'For half an hour''s allowance, what levels do the two criteria give?', '["OSHA 97.000000 dBA; NIOSH 110.000000 dBA.", "OSHA 115.000000 dBA; NIOSH 100.000000 dBA.", "OSHA 105.000000 dBA; NIOSH 94.000000 dBA.", "OSHA 110.000000 dBA; NIOSH 97.000000 dBA."]'::jsonb, 3, 'Half an hour is four halvings of 8 hours: four 5 dB steps above 90 on OSHA give 110.000000 dBA and four 3 dB steps above 85 on NIOSH give 97.000000 dBA. The 115 and 100 dBA pair is the quarter-hour row, one more halving, and 105 and 94 dBA is the one hour row.'),
  ('hygiene', 'beginner', 'final', null, 35, 'A contractor''s summary gives only a TWA of 80 dBA. What noise dose does it restate on each criterion?', '["25.000750 percent on OSHA and 31.622777 percent on NIOSH.", "31.622777 percent on OSHA and 25.000750 percent on NIOSH.", "25.000000 percent on both, since 80 dBA is two halvings.", "Nothing on OSHA, since 80 dBA is below the PEL threshold."]'::jsonb, 0, '`noiseDoseFromTwaPct` gives 25.000750 percent on OSHA and 31.622777 percent on NIOSH. The OSHA figure sits a hair above a quarter because of the printed 16.61. The threshold decides which periods count and plays no part in turning a TWA back into a noise dose, which is why a TWA under 90 still restates a noise dose above zero.'),
  ('hygiene', 'beginner', 'final', null, 36, 'Fed a TWA of 100 dBA, what does `noiseDoseFromTwaPct` return on OSHA and on NIOSH?', '["OSHA 399.987998 percent; NIOSH 1000.000000 percent.", "OSHA 399.987998 percent; NIOSH 3162.277660 percent.", "OSHA 3162.277660 percent; NIOSH 399.987998 percent.", "OSHA 200.000000 percent; NIOSH 316.227766 percent."]'::jsonb, 1, 'On OSHA 100 dBA is two steps above 90, so about four allowances, 399.987998 percent with the printed coefficient. On NIOSH it is 15 dB above 85, five 3 dB steps, 3162.277660 percent. 1000.000000 percent is the NIOSH figure at 95 dBA, and the pair 200.000000 and 316.227766 percent counts only one step up from each criterion level.'),
  ('hygiene', 'beginner', 'final', null, 37, 'On NIOSH, which TWA restates a noise dose of 50.118723 percent?', '["80 dBA.", "85 dBA.", "82 dBA.", "88 dBA."]'::jsonb, 2, '`noiseDoseFromTwaPct` gives 50.118723 percent on NIOSH at a TWA of 82 dBA, one 3 dB step below the 85 dBA criterion level and so close to half an allowance. At 80 dBA it gives 31.622777 percent, at 85 dBA 100.000000 percent and at 88 dBA 199.526231 percent. On OSHA the same 82 dBA gives 32.988490 percent.'),
  ('hygiene', 'beginner', 'final', null, 38, 'Planning a task against both criteria, which gives the stricter level for a given duration, and how does the gap move as the task gets shorter?', '["OSHA at every duration, and the gap narrows as the time shortens.", "NIOSH at long durations, OSHA at short ones, crossing near 4 hours.", "Neither; both give the same level once the time is under one hour.", "NIOSH at every duration, and the gap widens as the time shortens."]'::jsonb, 3, 'NIOSH starts lower, 85.000000 against 90.000000 dBA at 8 hours, and climbs 3 dB a halving against OSHA''s 5 dB, so the gap grows to 100.000000 against 115.000000 dBA at a quarter of an hour. Two ladders of different slope from two different starting levels never cross in this range.'),
  ('hygiene', 'beginner', 'final', null, 39, 'NIOSH Table 1-1 prints the reference duration from 80 dBA upward. How much of it does the engine reproduce?', '["It reproduces 49 rows, and one further printed row is refuted by the formula.", "It reproduces all 51 rows, the same count as OSHA Table G-16a.", "It reproduces none of them, since NIOSH prints hours and minutes.", "It reproduces 83 rows, one for each row of NIOSH Table 1-2."]'::jsonb, 0, 'Digest section 4: 49 rows are reproduced, plus one printed row the formula refutes, which is an erratum in the source and is read in a later tier. 51 is the row count of Table G-16a, and 83 belongs to Table 1-2, the noise dose to TWA table. The golden stores hours, which the engine compares against.'),
  ('hygiene', 'beginner', 'final', null, 40, 'A hygiene report mentions flare radiation near the work area. How does this course treat it?', '["It teaches flare radiation as a form of heat stress in this tier.", "It cites Separation and Relief, which owns radiant flux in kW/m2.", "It converts the radiant flux to a WBGT with the published weights.", "It treats it as a noise source, since flares are loud equipment."]'::jsonb, 1, 'Digest section 25: flare and pool-fire thermal radiation, in kW/m2, is owned by the Separation and Relief courses. It is a radiant flux on a surface, and heat stress here is a WBGT index and a body''s metabolic load, taught in the Expert tier. The course cites the seam and does not convert one quantity into the other.'),
  ('hygiene', 'beginner', 'final', null, 41, 'In what unit does the engine take the duration of each period of a noise dose record?', '["Minutes, as the NIOSH table prints.", "Seconds, as a dosimeter logs them.", "Hours, as `durationH` on each period.", "Percent of an 8 hour shift, as a share."]'::jsonb, 2, 'Digest section 25: durations are in hours for the noise dose, LEX and the 8-hour TWA, and in minutes for the STEL and the averages the Expert tier reads. The refusals name `periods[0].durationH`, the hours of a period. NIOSH Table 1-1 prints hours, minutes and seconds, and the golden stores hours.'),
  ('hygiene', 'beginner', 'final', null, 42, 'A report asks for the minutes left at a stated sound level on the OSHA PEL after a day''s record. Which method gives that figure?', '["The reference duration at the stated level, converted to minutes, in full.", "The PEL share already used, times 8 hours, converted into minutes.", "The share left on the action level, times its reference duration.", "The PEL share left, times the reference duration at that level, in minutes."]'::jsonb, 3, 'Digest section 9 derives it: after the OBEN day the PEL noise dose stands at 27.748183 percent, so 72.251817 percent of the allowance remains, and the fraction remaining times the reference duration gives 2.890073 h at 95 dBA, which is 173.404361 minutes. The whole reference duration ignores the share the day has already used. The share used times 8 hours answers nothing, and the action level has spent a different share of a different allowance.');
